import java.nio.file.*;import java.io.*;public class LogAnalyzer{public static void main(String[]x)throws Exception{Path d=Path.of("logs");Files.createDirectories(d);Files.writeString(d.resolve("app.log"),"INFO start\nERROR failed\nINFO done\n");long lines=0,hits=0;try(var st=Files.newDirectoryStream(d,"*.log")){for(Path p:st){try(var r=Files.newBufferedReader(p)){String s;while((s=r.readLine())!=null){lines++;if(s.contains("ERROR"))hits++;}}System.out.println(p+" size="+Files.size(p));}}System.out.println("Lines="+lines+", errors="+hits);}}
